import js from '@eslint/js'
import { defineConfig, globalIgnores } from 'eslint/config'
import reactHooks from 'eslint-plugin-react-hooks'
import globals from 'globals'
import tseslint from 'typescript-eslint'

const eslintConfig = defineConfig([
  globalIgnores([
    'dist/**',
    'build/**',
    '.wrangler/**',
    'node_modules/**',
    // Build inputs, not source: `assets/original/` is a 240 MB image pool,
    // `assets/static/` is served verbatim and `assets/generated/` is produced
    // by `python -m pipeline`.
    'assets/**',

    // Generated data only; regenerated by `python -m pipeline`. CI verifies it
    // matches the manifest, so linting it would only fight the generator.
    'worker/targets.js',
    'worker/slot_formats.js',
  ]),
  {
    files: ['**/*.{js,mjs,cjs}'],
    extends: [js.configs.recommended],
    languageOptions: {
      globals: {
        ...globals.node,
      },
    },
  },
  {
    files: ['**/*.{ts,tsx}'],
    extends: [...tseslint.configs.recommended],
    languageOptions: {
      ecmaVersion: 2022,
      sourceType: 'module',
      globals: {
        ...globals.browser,
        ...globals.node,
      },
    },
    plugins: {
      'react-hooks': reactHooks,
    },
    rules: {
      'react-hooks/rules-of-hooks': 'error',
      'react-hooks/exhaustive-deps': 'warn',
      // A leading underscore marks a binding that must exist but is deliberately
      // not referenced (e.g. event signatures kept for API parity).
      '@typescript-eslint/no-unused-vars': [
        'warn',
        {
          argsIgnorePattern: '^_',
          varsIgnorePattern: '^_',
          caughtErrorsIgnorePattern: '^_',
        },
      ],
    },
  },
])

export default eslintConfig
